<span class="line"><span style="color:#E5C07B;">IDatabase</span><span style="color:#E06C75;"> reader</span><span style="color:#56B6C2;"> =</span><span style="color:#E5C07B;"> slaveConn</span><span style="color:#ABB2BF;">.</span><span style="color:#61AFEF;">GetDatabase</span><span style="color:#ABB2BF;">();</span></span>
